<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\RefundService;

Auth::requirePermission('payments.manage');$tenantId=em_require_tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='refund'){
            Auth::requirePermission('refunds.manage');$paymentId=(int)($_POST['payment_id']??0);$reason=(string)($_POST['reason']??'');$r=(new RefundService())->requestFull($paymentId,$reason);em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno integral concluído e pedido cancelado.':'Estorno solicitado ao provedor. Status: '.$r['status'].'.');
        }elseif($action==='reconcile-refund'){
            Auth::requirePermission('refunds.manage');$refundId=(int)($_POST['refund_id']??0);$r=(new RefundService())->reconcile($refundId);em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno confirmado e concluído.':'O provedor ainda não confirmou o estorno.');
        }
    }catch(Throwable $e){em_flash('error',$e->getMessage());}
    em_go('payments');
}
$provider=trim((string)($_GET['provider']??''));$status=trim((string)($_GET['status']??''));$sql='SELECT p.*,o.status order_status,o.payment_status order_payment_status,c.name customer_name,r.id refund_id,r.status refund_status,r.reason refund_reason FROM payments p JOIN orders o ON o.id=p.order_id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN refunds r ON r.tenant_id=p.tenant_id AND r.payment_id=p.id WHERE p.tenant_id=?';$args=[$tenantId];if($provider!==''){$sql.=' AND p.provider=?';$args[]=$provider;}if($status!==''){$sql.=' AND p.status=?';$args[]=$status;}$sql.=' ORDER BY p.id DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($args);$payments=$s->fetchAll();
$w=$pdo->prepare('SELECT * FROM webhook_events WHERE tenant_id=? ORDER BY id DESC LIMIT 100');$w->execute([$tenantId]);$webhooks=$w->fetchAll();
$stats=[];foreach(['paid'=>'SELECT COALESCE(SUM(amount_cents),0) FROM payments WHERE tenant_id=? AND status="paid"','pending'=>'SELECT COUNT(*) FROM payments WHERE tenant_id=? AND status IN ("created","pending","authorized")','failed'=>'SELECT COUNT(*) FROM payments WHERE tenant_id=? AND status="failed"','refunded'=>'SELECT COALESCE(SUM(amount_cents),0) FROM payments WHERE tenant_id=? AND status="refunded"'] as $k=>$q){$x=$pdo->prepare($q);$x->execute([$tenantId]);$stats[$k]=$x->fetchColumn();}
em_header('Pagamentos','payments');
?><section class="grid"><div class="card metric"><span class="muted">Total confirmado</span><strong><?= em_money($stats['paid']) ?></strong></div><div class="card metric"><span class="muted">Estornado</span><strong><?= em_money($stats['refunded']) ?></strong></div><div class="card metric"><span class="muted">Pendentes</span><strong><?= (int)$stats['pending'] ?></strong></div><div class="card metric"><span class="muted">Falharam</span><strong><?= (int)$stats['failed'] ?></strong></div></section><section class="card" style="margin-top:18px"><form method="get" class="actions"><input type="hidden" name="route" value="payments"><select name="provider"><option value="">Todos provedores</option><?php foreach(['stripe','pagbank','mercadopago','manual'] as $pv):?><option value="<?= $pv ?>"<?= em_selected($provider,$pv) ?>><?= $pv ?></option><?php endforeach;?></select><select name="status"><option value="">Todos status</option><?php foreach(['created','pending','authorized','paid','failed','cancelled','refunded','partially_refunded'] as $st):?><option value="<?= $st ?>"<?= em_selected($status,$st) ?>><?= $st ?></option><?php endforeach;?></select><button class="secondary">Filtrar</button></form><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Pedido</th><th>Cliente</th><th>Provedor</th><th>Status</th><th>Valor</th><th>ID externo</th><th>Estorno</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td>#<?= (int)$p['id'] ?></td><td><a href="<?= Security::e(app_url('?route=orders&view='.(int)$p['order_id'])) ?>">#<?= (int)$p['order_id'] ?></a></td><td><?= Security::e($p['customer_name']??'—') ?></td><td><?= Security::e($p['provider']) ?></td><td><span class="badge"><?= Security::e($p['status']) ?></span><br><small><?= Security::e($p['verified_at']??'') ?></small></td><td><?= em_money($p['amount_cents']) ?></td><td><code><?= Security::e($p['provider_payment_id']??'—') ?></code></td><td><?php if($p['refund_id']):?><span class="badge"><?= Security::e($p['refund_status']) ?></span><br><small><?= Security::e($p['refund_reason']??'') ?></small><?php if(Auth::can('refunds.manage')&&$p['refund_status']==='provider_pending'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="reconcile-refund"><input type="hidden" name="refund_id" value="<?= (int)$p['refund_id'] ?>"><button class="secondary">Reverificar</button></form><?php elseif(Auth::can('refunds.manage')&&$p['refund_status']==='failed'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="reason" value="<?= Security::e($p['refund_reason']??'Nova tentativa de estorno') ?>"><button class="secondary">Tentar novamente</button></form><?php endif;?><?php elseif(Auth::can('refunds.manage')&&$p['status']==='paid'):?><form method="post" onsubmit="return confirm('Confirmar estorno integral? Esta operação devolve o valor ao cliente e cancela o pedido após confirmação do provedor.')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input name="reason" maxlength="500" required minlength="5" placeholder="Motivo do estorno" style="min-width:180px"><button class="secondary" style="margin-top:6px">Estornar integral</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php if(Auth::can('audit.view')):?><section class="card" style="margin-top:18px"><div class="section-head"><h2>Últimos webhooks</h2><span class="muted">Assinatura + idempotência</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Provedor</th><th>ID evento</th><th>Assinatura</th><th>Status</th><th>Processado</th></tr></thead><tbody><?php foreach($webhooks as $w):?><tr><td><?= Security::e($w['provider']) ?></td><td><code><?= Security::e($w['external_event_id']) ?></code></td><td><?= $w['signature_valid']?'Válida':'Inválida' ?></td><td><?= Security::e($w['status']) ?></td><td><?= Security::e($w['processed_at']??'—') ?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php em_footer();
